"""KAN-100 / KAN-99: p07d serves the build and backend on the browser sandbox's own loopback and runs the spec there."""
import asyncio
import json
from pathlib import Path
from types import SimpleNamespace

import pytest

from aether_os.core.sandbox.runner import SandboxUnavailable
from aether_os.phases.p07d_e2e_testing import task_agent


@pytest.fixture(autouse=True)
def no_model(monkeypatch):
    """The spec is generated by a model when one answers; here it never does (the fallback spec is used)."""
    class Llm:
        async def call(self, *a, **k):
            return ""
    monkeypatch.setattr("aether_os.core.llm.client.get_llm_client", lambda *a, **k: Llm())


@pytest.fixture()
def proj(tmp_path):
    (tmp_path / "frontend" / "dist").mkdir(parents=True)
    (tmp_path / "frontend" / "dist" / "index.html").write_text("<html></html>")
    (tmp_path / "backend" / "src").mkdir(parents=True)
    (tmp_path / "backend" / "src" / "main.py").write_text("app = None\n")
    return tmp_path


def _data(proj, **extra):
    return {"frontend_output_path": str(proj / "frontend"), "backend_output_path": str(proj / "backend"),
            "project_name": "x", "entities": [{"name": "Item", "table": "items"}], **extra}


def test_spec_runs_in_the_sandbox_against_the_in_sandbox_loopback(proj, monkeypatch):
    seen = []

    async def fake_job(job, *, project, timeout=120):
        seen.append(job)
        Path(job["out"]).write_text(json.dumps({"stats": {"expected": 3, "unexpected": 1}}))
        return {"ok": True}
    monkeypatch.setattr(task_agent, "run_browser_job", fake_job)
    monkeypatch.setattr(task_agent.phase_exec, "project_root", lambda p: proj)

    out = proj / "p07d"
    r = asyncio.run(task_agent.run(SimpleNamespace(input_data=_data(proj)), [], out))
    job = seen[0]
    assert job["action"] == "playwright_test" and job["serve"]["dir"] == str(proj / "frontend" / "dist")
    assert job["backend"]["argv"][:4] == ["python3", "-m", "uvicorn", "src.main:app"] and job["backend"]["port"] == 8000
    assert "127.0.0.1:5173" in (out / "e2e.spec.ts").read_text() + (out / "playwright.config.ts").read_text()
    assert (r.metadata["passed"], r.metadata["failed"]) == (3, 1)


def test_no_build_defers_and_no_sandbox_never_falls_back_to_the_host(proj, monkeypatch, tmp_path):
    r = asyncio.run(task_agent.run(SimpleNamespace(input_data={"frontend_url": "http://localhost:5173"}), [], tmp_path / "o"))
    assert r.metadata["skipped"] is True

    async def down(job, *, project, timeout=120):
        raise SandboxUnavailable("no docker")
    monkeypatch.setattr(task_agent, "run_browser_job", down)
    monkeypatch.setattr(task_agent.phase_exec, "project_root", lambda p: proj)
    with pytest.raises(SandboxUnavailable):
        asyncio.run(task_agent.run(SimpleNamespace(input_data=_data(proj)), [], proj / "p07d"))
